internal static class CompanionProgram {
 internal static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CompagnonDofus");
 internal static readonly string Installed=Path.Combine(Root,"App","CompagnonDofus.exe");
 [STAThread]static int Main(string[] args){try{SongesCapture.SetProcessDPIAware();if(args.Length==2&&args[0]=="--finish-update"){int parent;if(!Int32.TryParse(args[1],out parent)||parent<=0)throw new InvalidDataException("Processus invalide.");try{using(var process=Process.GetProcessById(parent))if(!process.WaitForExit(60000))throw new IOException("Fermez le compagnon avant de réessayer.");}catch(ArgumentException){}Install();return 0;}if(args.Length==2&&args[0]=="--quest-capture-ocr-test")return QuestCaptureAcceptance.RunOcr(args[1]);if(args.Length==2&&args[0]=="--catalogue-bootstrap")return GuideLibrary.Export(args[1]).GetAwaiter().GetResult();if(args.Length==2&&args[0]=="--songes-ocr-test")return SongesOcrAcceptance.Run(args[1]);if(args.Length==2&&args[0]=="--ganymede-reader-test")return StandaloneTests.ReaderTest(args[1]);if(args.Length==2&&args[0]=="--self-test")return StandaloneTests.Run(args[1]);if(args.Contains("--install")){Install();return 0;}bool created;using(var mutex=new Mutex(true,"Local\\CompagnonDofus.Standalone",out created)){if(!created){MessageBox.Show("Le compagnon est déjà ouvert. Retrouvez-le avec Alt + Tab.","Compagnon Dofus");return 0;}if(String.Equals(Path.GetFullPath(Assembly.GetExecutingAssembly().Location),Path.GetFullPath(Installed),StringComparison.OrdinalIgnoreCase))try{CompanionShellIcon.Refresh(false);}catch(Exception ex){Trace.WriteLine("Actualisation icône : "+ex.Message);}var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};app.DispatcherUnhandledException+=delegate(object sender,System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e){MessageBox.Show(e.Exception.Message,"Compagnon Dofus");e.Handled=true;};var overlay=new CompanionWindow(new Store(Path.Combine(Root,"Data")));app.Dispatcher.BeginInvoke(new Action(overlay.OpenLibrary));app.Run();return 0;}}catch(Exception ex){MessageBox.Show("Le compagnon n’a pas pu démarrer.\n"+ex.Message+"\n\nVos données : "+Root,"Compagnon Dofus",MessageBoxButton.OK,MessageBoxImage.Error);return 1;}}
 internal static void Install(){Directory.CreateDirectory(Path.GetDirectoryName(Installed));string source=Assembly.GetExecutingAssembly().Location;if(!String.Equals(Path.GetFullPath(source),Path.GetFullPath(Installed),StringComparison.OrdinalIgnoreCase)){string[] dependencies={"SkiaSharp.dll","libSkiaSharp.dll","System.Memory.dll","System.Buffers.dll","System.Runtime.CompilerServices.Unsafe.dll","System.Numerics.Vectors.dll","THIRD_PARTY_NOTICES.txt"};string sourceDirectory=Path.GetDirectoryName(source);foreach(string name in dependencies)if(!File.Exists(Path.Combine(sourceDirectory,name)))throw new IOException("Fichier manquant : "+name+". Extrayez tout le ZIP avant d’installer.");foreach(string name in dependencies){string target=Path.Combine(Path.GetDirectoryName(Installed),name);string pending=target+".new";File.Copy(Path.Combine(sourceDirectory,name),pending,true);if(File.Exists(target))File.Replace(pending,target,null);else File.Move(pending,target);}var temporary=Installed+".new";File.Copy(source,temporary,true);if(File.Exists(Installed))File.Replace(temporary,Installed,null);else File.Move(temporary,Installed);}CompanionShellIcon.Refresh(true);MessageBox.Show("Compagnon Dofus installé.\nLe raccourci est disponible sur le bureau et dans le menu Démarrer.\n\nAucune donnée de Mon espace n’a été modifiée.","Compagnon Dofus");Process.Start(new ProcessStartInfo(Installed){UseShellExecute=true});}
